func _run_tests() -> void:
	var bullet_scene: PackedScene = load("res://bullet.tscn")
	if not check("bullet_exists", bullet_scene != null, "La scena res://bullet.tscn deve essere caricata senza errori"):
		return
	var b := bullet_scene.instantiate() as Area2D
	if not check("is_area", b != null, "La radice di bullet.tscn deve essere un Area2D"):
		return

	check("mask_check", b.collision_mask == 6, "La collision_mask del proiettile deve valere 6 (layer 2 Muri + layer 4 Guardie)")
	check("layer_check", b.collision_layer == 0, "Il collision_layer del proiettile deve essere 0")

	var main := await instantiate_main_scene()
	if main == null:
		b.free()
		return

	main.add_child(b)
	await wait_frames(1)

	var dummy := StaticBody2D.new()
	main.add_child(dummy)

	if has_function(b, "_on_body_entered"):
		call_if_exists(b, "_on_body_entered", [dummy])
	else:
		b.body_entered.emit(dummy)

	check("bullet_destroyed", b.is_queued_for_deletion(), "Il proiettile deve distruggersi con queue_free() quando impatta contro un corpo")
	dummy.queue_free()
	if not b.is_queued_for_deletion():
		b.queue_free()
